  set animation_offset_end(v: H.In<number>);
  /** Number of frames to ignore from the end of the underlying source. The source content is trimmed, and future frames are turned into holds Range: 0 to 2147483647. Default: 0. */
  get content_trim_end(): H.Ref<number>;
  set content_trim_end(v: H.In<number>);
