/**
 * Generate Worley noise based on the distance to random points. Typically used to generate textures such as stones, water, or biological cells
 *
 * bpy.types.ShaderNodeTexVoronoi
 */
export interface ShaderNodeTexVoronoi extends R.ShaderNode {
  /** Texture coordinate mapping settings */
  get texture_mapping(): H.Own<R.TexMapping>;
  /** Color mapping settings */
  get color_mapping(): H.Own<R.ColorMapping>;
  /**
   * Number of dimensions to output noise for Default: '1D'.
   * - `1D`: 1D (Use the scalar value W as input)
   * - `2D`: 2D (Use the 2D vector (X, Y) as input. The Z component is ignored.)
   * - `3D`: 3D (Use the 3D vector (X, Y, Z) as input)
   * - `4D`: 4D (Use the 4D vector (X, Y, Z, W) as input)
   */
  get voronoi_dimensions(): H.Ref<"1D" | "2D" | "3D" | "4D">;
  set voronoi_dimensions(v: H.In<"1D" | "2D" | "3D" | "4D">);
  /**
   * The distance metric used to compute the texture Default: 'EUCLIDEAN'.
   * - `EUCLIDEAN`: Euclidean (Euclidean distance)
   * - `MANHATTAN`: Manhattan (Manhattan distance)
   * - `CHEBYCHEV`: Chebychev (Chebychev distance)
   * - `MINKOWSKI`: Minkowski (Minkowski distance)
   */
  get distance(): H.Ref<"EUCLIDEAN" | "MANHATTAN" | "CHEBYCHEV" | "MINKOWSKI">;
  set distance(v: H.In<"EUCLIDEAN" | "MANHATTAN" | "CHEBYCHEV" | "MINKOWSKI">);
  /**
   * The Voronoi feature that the node will compute Default: 'F1'.
   * - `F1`: F1 (Computes the distance to the closest point as well as its position and color)
   * - `F2`: F2 (Computes the distance to the second closest point as well as its position and color)
   * - `SMOOTH_F1`: Smooth F1 (Smoothed version of F1. Weighted sum of neighbor voronoi cells.)
   * - `DISTANCE_TO_EDGE`: Distance to Edge (Computes the distance to the edge of the voronoi cell)
   * - `N_SPHERE_RADIUS`: N-Sphere Radius (Computes the radius of the n-sphere inscribed in the voronoi cell)
   */
  get feature(): H.Ref<"F1" | "F2" | "SMOOTH_F1" | "DISTANCE_TO_EDGE" | "N_SPHERE_RADIUS">;
  set feature(v: H.In<"F1" | "F2" | "SMOOTH_F1" | "DISTANCE_TO_EDGE" | "N_SPHERE_RADIUS">);
  /** Normalize output Distance to 0.0 to 1.0 range Default: False. */
  get normalize(): H.Ref<boolean>;
  set normalize(v: H.In<boolean>);
  /** Input socket template */
  input_template(index: H.In<number>): H.Ptr<R.NodeInternalSocketTemplate>;
  /** Input socket template */
  input_template(kw: { index: H.In<number> }): H.Ptr<R.NodeInternalSocketTemplate>;
  /** Output socket template */
  output_template(index: H.In<number>): H.Ptr<R.NodeInternalSocketTemplate>;
  /** Output socket template */
  output_template(kw: { index: H.In<number> }): H.Ptr<R.NodeInternalSocketTemplate>;
  readonly inputs: R.Node["inputs"] & {
    /** This node's inputs by name (any other name is a NodeSocket). */
    readonly $: {
      readonly "Vector": H.Ptr<R.NodeSocketVector>;
      readonly "W": H.Ptr<R.NodeSocketFloat>;
      readonly "Scale": H.Ptr<R.NodeSocketFloat>;
      readonly "Detail": H.Ptr<R.NodeSocketFloat>;
      readonly "Roughness": H.Ptr<R.NodeSocketFloatFactor>;
      readonly "Lacunarity": H.Ptr<R.NodeSocketFloat>;
      readonly "Smoothness": H.Ptr<R.NodeSocketFloatFactor>;
      readonly "Exponent": H.Ptr<R.NodeSocketFloat>;
      readonly "Randomness": H.Ptr<R.NodeSocketFloatFactor>;
    };
  };
  readonly outputs: R.Node["outputs"] & {
    /** This node's outputs by name (any other name is a NodeSocket). */
    readonly $: {
      readonly "Distance": H.Ptr<R.NodeSocketFloat>;
      readonly "Color": H.Ptr<R.NodeSocketColor>;
      readonly "Position": H.Ptr<R.NodeSocketVector>;
      readonly "W": H.Ptr<R.NodeSocketFloat>;
      readonly "Radius": H.Ptr<R.NodeSocketFloat>;
    };
  };
}

