  set offset(v: H.In<number>);
  /** Limit the distance used for projection (zero disables) Range: 0 to inf. Default: 0.0. */
  get project_limit(): H.Ref<number>;
  set project_limit(v: H.In<number>);
  /** X Default: False. */
  get use_project_x(): H.Ref<boolean>;
  set use_project_x(v: H.In<boolean>);
  /** Y Default: False. */
  get use_project_y(): H.Ref<boolean>;
  set use_project_y(v: H.In<boolean>);
  /** Z Default: False. */
  get use_project_z(): H.Ref<boolean>;
  set use_project_z(v: H.In<boolean>);
  /** Number of subdivisions that must be performed before extracting vertices' positions and normals Range: 0 to 6. Default: 0. */
  get subsurf_levels(): H.Ref<number>;
  set subsurf_levels(v: H.In<number>);
  /** Allow vertices to move in the negative direction of axis Default: False. */
  get use_negative_direction(): H.Ref<boolean>;
  set use_negative_direction(v: H.In<boolean>);
  /** Allow vertices to move in the positive direction of axis Default: True. */
  get use_positive_direction(): H.Ref<boolean>;
  set use_positive_direction(v: H.In<boolean>);
  /** When projecting in the negative direction invert the face cull mode Default: False. */
  get use_invert_cull(): H.Ref<boolean>;
  set use_invert_cull(v: H.In<boolean>);
  /** Invert vertex group influence Default: False. */
  get invert_vertex_group(): H.Ref<boolean>;
  set invert_vertex_group(v: H.In<boolean>);
