  /** General Mass value Range: 0 to 50000. Default: 0.0. */
  get mass(): H.Ref<number>;
  set mass(v: H.In<number>);
  /** Control point mass values Default: "". */
  get vertex_group_mass(): H.Ref<string>;
  set vertex_group_mass(v: H.In<string>);
  /** Apply gravitation to point movement Range: -10 to 10. Default: 0.0. */
  get gravity(): H.Ref<number>;
  set gravity(v: H.In<number>);
  /** Tweak timing for physics to control frequency and speed Range: 0.009999999776482582 to 100. Default: 0.0. */
  get speed(): H.Ref<number>;
  set speed(v: H.In<number>);
  /** Control point weight values Default: "". */
  get vertex_group_goal(): H.Ref<string>;
  set vertex_group_goal(v: H.In<string>);
  /** Goal minimum, vertex weights are scaled to match this range Range: 0 to 1. Default: 0.0. */
  get goal_min(): H.Ref<number>;
  set goal_min(v: H.In<number>);
  /** Goal maximum, vertex weights are scaled to match this range Range: 0 to 1. Default: 0.0. */
  get goal_max(): H.Ref<number>;
  set goal_max(v: H.In<number>);
  /** Default Goal (vertex target position) value Range: 0 to 1. Default: 0.0. */
  get goal_default(): H.Ref<number>;
  set goal_default(v: H.In<number>);
  /** Goal (vertex target position) spring stiffness Range: 0 to 0.9990000128746033. Default: 0.0. */
  get goal_spring(): H.Ref<number>;
  set goal_spring(v: H.In<number>);
  /** Goal (vertex target position) friction Range: 0 to 50. Default: 0.0. */
  get goal_friction(): H.Ref<number>;
  set goal_friction(v: H.In<number>);
  /** Edge spring stiffness when longer than rest length Range: 0 to 0.9990000128746033. Default: 0.0. */
  get pull(): H.Ref<number>;
  set pull(v: H.In<number>);
  /** Edge spring stiffness when shorter than rest length Range: 0 to 0.9990000128746033. Default: 0.0. */
  get push(): H.Ref<number>;
  set push(v: H.In<number>);
  /** Edge spring friction Range: 0 to 50. Default: 0.0. */
  get damping(): H.Ref<number>;
  set damping(v: H.In<number>);
  /** Alter spring length to shrink/blow up (unit %) 0 to disable Range: 0 to 200. Default: 0. */
