  set aero(v: H.In<number>);
  /** Permanent deform Range: 0 to 100. Default: 0. */
  get plastic(): H.Ref<number>;
  set plastic(v: H.In<number>);
  /** Bending Stiffness Range: 0 to 10. Default: 0.0. */
  get bend(): H.Ref<number>;
  set bend(v: H.In<number>);
  /** Shear Stiffness Range: 0 to 1. Default: 0.0. */
  get shear(): H.Ref<number>;
  set shear(v: H.In<number>);
  /** Control point spring strength values Default: "". */
  get vertex_group_spring(): H.Ref<string>;
  set vertex_group_spring(v: H.In<string>);
  /**
   * Choose Collision Type Default: 'MANUAL'.
   * - `MANUAL`: Manual (Manual adjust)
   * - `AVERAGE`: Average (Average Spring length * Ball Size)
   * - `MINIMAL`: Minimal (Minimal Spring length * Ball Size)
   * - `MAXIMAL`: Maximal (Maximal Spring length * Ball Size)
   * - `MINMAX`: AvMinMax ((Min+Max)/2 * Ball Size)
   */
  get collision_type(): H.Ref<"MANUAL" | "AVERAGE" | "MINIMAL" | "MAXIMAL" | "MINMAX">;
  set collision_type(v: H.In<"MANUAL" | "AVERAGE" | "MINIMAL" | "MAXIMAL" | "MINMAX">);
