  /** Blending to inelastic collision Range: 0.0010000000474974513 to 1. Default: 0.0. */
  get ball_damp(): H.Ref<number>;
  set ball_damp(v: H.In<number>);
  /** The Runge-Kutta ODE solver error limit, low value gives more precision, high values speed Range: 0.0010000000474974513 to 10. Default: 0.0. */
  get error_threshold(): H.Ref<number>;
  set error_threshold(v: H.In<number>);
  /** Minimal # solver steps/frame Range: 0 to 30000. Default: 0. */
  get step_min(): H.Ref<number>;
  set step_min(v: H.In<number>);
  /** Maximal # solver steps/frame Range: 0 to 30000. Default: 0. */
  get step_max(): H.Ref<number>;
