  /** Material slot index of this curve Range: 0 to 32767. Default: 0. */
  get material_index(): H.Ref<number>;
  set material_index(v: H.In<number>);
  /** Location of this character in the text data (only for text curves) Range: 0 to 2147483647. Default: 0. */
  get character_index(): H.Ref<number>;
  /**
   * Calculate spline length
   * @param resolution Spline resolution to be used, 0 defaults to the resolution_u
   */
  calc_length(resolution?: H.In<number>): H.Ref<number>;
  /**
   * Calculate spline length
   * @param resolution Spline resolution to be used, 0 defaults to the resolution_u
   */
  calc_length(kw: {
    /** Spline resolution to be used, 0 defaults to the resolution_u */
    resolution?: H.In<number>;
  }): H.Ref<number>;
  /**
   * Return the message
   * @param direction The direction where 0-1 maps to U-V
   */
  valid_message(direction: H.In<number>): H.Ref<string>;
  /**
   * Return the message
   * @param direction The direction where 0-1 maps to U-V
   */
