/**
 * Subdivision surface modifier
 *
 * bpy.types.SubsurfModifier
 */
export interface SubsurfModifier extends R.Modifier {
  /**
   * Controls how smoothing is applied to UVs Default: 'PRESERVE_BOUNDARIES'.
   * - `NONE`: None (UVs are not smoothed, boundaries are kept sharp)
   * - `PRESERVE_CORNERS`: Keep Corners (UVs are smoothed, corners on discontinuous boundary are kept sharp)
   * - `PRESERVE_CORNERS_AND_JUNCTIONS`: Keep Corners, Junctions (UVs are smoothed, corners on discontinuous boundary and junctions of 3 or more regions are kept sharp)
   * - `PRESERVE_CORNERS_JUNCTIONS_AND_CONCAVE`: Keep Corners, Junctions, Concave (UVs are smoothed, corners on discontinuous boundary, junctions of 3 or more regions and darts and concave corners are kept sharp)
   * - `PRESERVE_BOUNDARIES`: Keep Boundaries (UVs are smoothed, boundaries are kept sharp)
   * - `SMOOTH_ALL`: All (UVs and boundaries are smoothed)
   */
  get uv_smooth(): H.Ref<"NONE" | "PRESERVE_CORNERS" | "PRESERVE_CORNERS_AND_JUNCTIONS" | "PRESERVE_CORNERS_JUNCTIONS_AND_CONCAVE" | "PRESERVE_BOUNDARIES" | "SMOOTH_ALL">;
  set uv_smooth(v: H.In<"NONE" | "PRESERVE_CORNERS" | "PRESERVE_CORNERS_AND_JUNCTIONS" | "PRESERVE_CORNERS_JUNCTIONS_AND_CONCAVE" | "PRESERVE_BOUNDARIES" | "SMOOTH_ALL">);
  /** Accuracy of vertex positions, lower value is faster but less precise Range: 1 to 10. Default: 3. */
  get quality(): H.Ref<number>;
  set quality(v: H.In<number>);
  /**
   * Controls how open boundaries are smoothed Default: 'ALL'.
   * - `PRESERVE_CORNERS`: Keep Corners (Smooth boundaries, but corners are kept sharp)
   * - `ALL`: All (Smooth boundaries, including corners)
   */
  get boundary_smooth(): H.Ref<"PRESERVE_CORNERS" | "ALL">;
  set boundary_smooth(v: H.In<"PRESERVE_CORNERS" | "ALL">);
  /**
   * Select type of subdivision algorithm Default: 'CATMULL_CLARK'.
   * - `CATMULL_CLARK`: Catmull-Clark (Create a smooth curved surface using the Catmull-Clark subdivision scheme)
   * - `SIMPLE`: Simple (Subdivide faces without changing shape)
   */
  get subdivision_type(): H.Ref<"CATMULL_CLARK" | "SIMPLE">;
  set subdivision_type(v: H.In<"CATMULL_CLARK" | "SIMPLE">);
  /** Number of subdivisions to perform in the 3D viewport Range: 0 to 11. Default: 1. */
  get levels(): H.Ref<number>;
  set levels(v: H.In<number>);
  /** Number of subdivisions to perform when rendering Range: 0 to 11. Default: 2. */
  get render_levels(): H.Ref<number>;
  set render_levels(v: H.In<number>);
  /** Skip displaying interior subdivided edges Default: True. */
  get show_only_control_edges(): H.Ref<boolean>;
  set show_only_control_edges(v: H.In<boolean>);
  /** Use mesh crease information to sharpen edges or corners Default: True. */
  get use_creases(): H.Ref<boolean>;
  set use_creases(v: H.In<boolean>);
  /** Interpolates existing custom normals to resulting mesh Default: False. */
  get use_custom_normals(): H.Ref<boolean>;
  set use_custom_normals(v: H.In<boolean>);
  /** Place vertices at the surface that would be produced with infinite levels of subdivision (smoothest possible shape) Default: True. */
  get use_limit_surface(): H.Ref<boolean>;
  set use_limit_surface(v: H.In<boolean>);
  /** Adaptively subdivide mesh based on camera distance Default: False. */
  get use_adaptive_subdivision(): H.Ref<boolean>;
  set use_adaptive_subdivision(v: H.In<boolean>);
  /**
   * How to adaptively subdivide the mesh Default: 'PIXEL'.
   * - `PIXEL`: Pixel (Subdivide polygons to reach a specified pixel size on screen)
   * - `OBJECT`: Object (Subdivide to reach a specified edge length in object space. This is required to use adaptive subdivision for instanced meshes)
   */
  get adaptive_space(): H.Ref<"PIXEL" | "OBJECT">;
  set adaptive_space(v: H.In<"PIXEL" | "OBJECT">);
  /** Target polygon pixel size for adaptive subdivision Range: 0.10000000149011612 to 1000. Default: 1.0. */
  get adaptive_pixel_size(): H.Ref<number>;
  set adaptive_pixel_size(v: H.In<number>);
  /** Target object space edge length for adaptive subdivision Range: 0.00009999999747378752 to 1000. Default: 0.01. */
  get adaptive_object_edge_length(): H.Ref<number>;
  set adaptive_object_edge_length(v: H.In<number>);
  /** Default: False. */
  get open_adaptive_subdivision_panel(): H.Ref<boolean>;
  set open_adaptive_subdivision_panel(v: H.In<boolean>);
  /** Default: False. */
  get open_advanced_panel(): H.Ref<boolean>;
  set open_advanced_panel(v: H.In<boolean>);
}

